package guidancecontent

import (
	"github.com/jaxxstorm/fed/internal/readiness"
	"io/fs"
)

// VER returns all 147 source-pinned evaluation/reporting variants as drafts.
func VER(rules, markdown fs.FS) (readiness.Package, error) {
	return cdvBuild(rules, markdown, "VER", "vulnerability-evaluation-and-reporting", map[string]cdvRecipe{
		"VER-FRP-ARP": {
			"Preserve FedRAMP's authority to require additional vulnerability reporting under specific agreements.", "FedRAMP agreement or corrective-action owner",
			"FedRAMP as the actor, additional information/reports/frequencies as a condition of a Corrective Action Plan or other federal-agency agreements; not a standing provider reporting mandate.",
			"Identify the applicable corrective-action plan or agreement and its reporting conditions and responsible parties.",
			"If exercising this authority, specify the additional information, alternative report or reporting frequency in the applicable condition and communicate it to the affected provider.",
			"applicable plan/agreement, attributable FedRAMP reporting condition and communication identifying the requested content and frequency.",
			"Check the condition belongs to the applicable agreement and was actually imposed; do not infer a universal alternative reporting cadence.",
			"An imagined FedRAMP request or a generic corrective-action template used as an active provider obligation.",
		},
		"VER-FRP-ADV": {
			"Preserve necessary-party access to sensitive vulnerability details when FedRAMP requires them for review or investigation.", "FedRAMP review or investigation owner",
			"FedRAMP may require additional vulnerability information, including exploit-enabling sensitive details, for review, response or investigation by necessary parties.",
			"Identify the actual review/response/investigation, the necessary parties and requested information scope.",
			"If exercising the permission, issue an attributable information request tied to the review, response or investigation and its necessary recipients.",
			"request authority/context, specific information request, necessary-party recipient mapping and associated communications.",
			"Confirm an actual FedRAMP requirement and its scope before treating sensitive detail disclosure as a provider duty.",
			"A routine public report or a fabricated investigation used to justify unrestricted sensitive disclosure.",
		},
		"VER-AGM-RVR": {
			"Help agencies evaluate provider vulnerability reports in the context of their authorization risk posture.", "Agency authorizing and security monitoring officials",
			"Agency review at appropriate/reasonable intervals commensurate with the ATO, with recommended automated processing/filtering of machine-readable provider information; the provider inventory excludes this audience.",
			"Locate the agency ATO risk posture, provider reports and machine-readable feeds; choose review intervals and filters justified by agency use and risk.",
			"Review reports on the chosen risk-appropriate cycle and use automated processing/filtering under the SHOULD statements. Consider the note's focus on overdue/accepted PAIN > 2, its higher-risk/service-mitigation exceptions, and accepted-item review when added or agency use/authorization changes.",
			"ATO risk basis, review-cycle/filter decisions, provider report versions, automated processing output and dated agency review conclusions.",
			"Compare review choices with actual agency risk posture and note exceptions; verify filtering does not hide provider-recommended mitigation or higher-risk-system issues.",
			"A universal fixed review interval or provider-authored claim that an agency reviewed its reports.",
		},
		"VER-AGM-MAP": {
			"Connect provider vulnerability information to agency POA&Ms where agency policy makes it relevant.", "Agency security program owner",
			"Agency security programs and relevant provider vulnerability information, including agency mitigation or continued use with accepted vulnerabilities that put agency systems at risk.",
			"Identify agency policy relevance criteria, provider report inputs and agency mitigation/authorization decisions requiring POA&M tracking.",
			"Use reported provider vulnerability information to maintain agency POA&Ms when relevant under agency policies, retaining the connection to agency actions and risk.",
			"agency policy criteria, provider report versions, relevance determinations and linked POA&M entries or documented non-relevance decisions.",
			"Trace relevant vulnerabilities to agency POA&M updates and explain non-relevant items; do not invent an agency entry from a provider ticket.",
			"A provider remediation backlog presented as the agency's POA&M or an assumption that every report item requires an agency milestone.",
		},
		"VER-EVA-ELX": {
			"Determine likely exploitability in the actual offering rather than equating scanner severity with practical exploitation.", "Provider vulnerability evaluator and resource owner",
			"Every detected vulnerability in its cloud-service context, using the defined likely-exploitable concept and realistic operating circumstances.",
			"Collect vulnerability details, affected versions, deployment configuration, exposure paths, prerequisites and existing protections needed to assess realistic exploitation.",
			"Evaluate each detected vulnerability's likely exploitability in the offering, documenting the contextual reasoning and supporting facts, including evidence for a not-likely-exploitable conclusion.",
			"stable vulnerability IDs, detection records, affected-resource context, exploit prerequisites, protection evidence and dated exploitability conclusions with evaluator identity.",
			"Challenge unsupported not-likely conclusions and compare reasoning with real configuration and plausible exploitation; the narrative prescribes no specific scoring framework.",
			"A low scanner score, absence of observed attacks or an unsupported assertion that exploitation is unlikely.",
		},
		"VER-EVA-EIR": {
			"Identify vulnerabilities reachable by internet-origin payloads, including indirect application paths.", "Provider vulnerability evaluator and application/network owners",
			"Detected vulnerabilities in the offering; internet reachability includes payloads reaching internal resources indirectly, not just direct internet accessibility.",
			"Trace internet-origin data through load balancers, applications, queues, logs and backend processing to affected components. Identify interception, inspection, filtering or sanitization that prevents triggering payloads from being processed.",
			"Evaluate whether an internet-origin payload can reach and trigger the vulnerability in the actual deployment. Record effective prevention and the facts supporting both reachable and non-reachable classifications.",
			"vulnerability/resource IDs, data-flow paths, application/configuration evidence, payload-prevention controls and dated reachability conclusions with supporting observations.",
			"Follow indirect paths such as SQL injection or vulnerable logging behind private networks; check prevention happens before vulnerable processing rather than inferring non-reachability from private addresses.",
			"A private subnet, firewall diagram or lack of a public IP without examining indirect internet payload processing.",
		},
		"VER-EVA-EPA": {
			"Assign PAIN from likely effects on agency customers in the offering's context.", "Provider impact evaluator and service/customer owners",
			"Detected vulnerabilities and likely potential agency impact of exploitation; distinguish N0 through N5 and one versus multiple agency effects using the defined minimal, narrow, disruptive and debilitating effects.",
			"Map affected service functions and customer dependencies to agency consequences, the number of affected agencies and the official customer-effect definitions.",
			"Evaluate likely exploitation effects on government customers and assign the corresponding PAIN rating. Explain the selected rating and why adjacent categories do not fit, including N0 where adverse effects are extremely unlikely. Under the Debilitating Customer Effect definition, unknown adverse customer effects should be treated as debilitating until proven otherwise; preserve uncertainty about affected-agency count rather than inventing it.",
			"vulnerability and service-context records, agency effect analysis, affected-agency count basis, selected PAIN and dated evaluator rationale linked to the official rating definitions.",
			"Compare impact evidence against every relevant rating boundary; check N4's debilitating-one OR disruptive-multiple distinction and N5's debilitating-multiple distinction. Do not substitute CVSS severity for agency effects.",
			"A scanner severity mapped mechanically to PAIN without agency customer-effect analysis or affected-agency scope.",
		},
		"VER-EVA-AIA": {
			"Avoid understating exploitability by assuming attackers must act manually.", "Provider vulnerability evaluator",
			"Exploitation of vulnerabilities is assumed automatable unless evidence proves otherwise; the exception is evidentiary, not an evaluator preference.",
			"Identify evaluations that rely on non-automatable exploitation and locate the technical evidence supporting that exception.",
			"Assume exploitation can be automated. Depart from that assumption only where evidence proves otherwise and retain that evidence with the vulnerability evaluation.",
			"evaluation records identifying the automation assumption and any exception's technical proof, tested conditions and evaluator rationale.",
			"Check every non-automatable conclusion has evidence establishing the exception in the actual context, rather than mere lack of a published automated exploit.",
			"No known exploit script, perceived attack complexity or an analyst's opinion without evidence proving non-automation.",
		},
		"VER-EVA-GRV": {
			"Consolidate vulnerability response where context supports logical resource groupings.", "Provider vulnerability evaluation lead",
			"Logical groups of affected information resources in the offering; after grouping, VDR applies to the consolidated vulnerability groups instead of individual detected instances.",
			"Identify affected-resource relationships, common vulnerability context and candidate groups; retain membership and the rationale for improved response efficiency/effectiveness.",
			"Evaluate and use logical groupings under the SHOULD rule, track group membership and apply VDR to each consolidated group. Revisit groups when resource context or membership changes.",
			"detection-instance to group mapping, grouping rationale, group-level evaluations, response history and membership revisions.",
			"Reconcile every detected instance to a defensible group or individual record; verify group-level response covers all members and does not hide materially different risk contexts.",
			"Deduplicated scanner counts with no group membership, contextual justification or group-level response.",
		},
		"VER-EVA-EFP": {
			"Distinguish false detections from real vulnerabilities with low exploitability.", "Provider vulnerability evaluator and component owner",
			"Detected vulnerabilities evaluated in the offering's actual context against the false-positive definition; a mitigated or unlikely vulnerability is not automatically a false positive.",
			"Collect the detector's finding, component/version/configuration facts and methods to confirm whether the vulnerability is actually present.",
			"Evaluate potential false positives using service context and retain technical justification for the disposition. The definition includes installed code never loaded, running or in an operating state required for exploitation; prove the vulnerability is not and was not present in an exploitable state. A formerly present vulnerability that was remediated or fully mitigated cannot also be a false positive.",
			"original finding, affected-component/version facts, historical loading/running/operating-state evidence, validation observations and dated false-positive or confirmed-vulnerability determination.",
			"Compare the false-positive rationale with actual detection and component facts; distinguish erroneous detection from an exploitation barrier.",
			"A suppression flag or firewall mitigation used as the sole evidence that the detection was false.",
		},
		"VER-EVA-EFA": {
			"Evaluate vulnerability context across all eight named factors rather than a single score.", "Provider vulnerability evaluator and architecture owner",
			"At least criticality, reachability, exploitability, detectability, prevalence, privilege, proximate vulnerabilities and known threats for detected vulnerabilities in the offering.",
			"Map each factor to available resource, architecture, identity, threat and prior-vulnerability information; identify missing contextual inputs.",
			"Consider each named factor in evaluation, including interactions with partially or fully mitigated vulnerabilities, and retain the effect of those considerations on the conclusion.",
			"factor-by-factor evaluation records with service criticality, data paths, exploit conditions, discoverability, affected population, privilege consequences, interacting vulnerabilities and known-threat inputs.",
			"Check each factor was substantively considered, especially proximate vulnerabilities and privilege effects; explain uncertainties instead of replacing the factor review with a scanner score.",
			"A severity score or eight checked boxes without contextual facts and evaluation reasoning.",
		},
		"VER-RPT-PER": {
			"Give necessary parties a complete persistent account of vulnerability detection and response activity.", "Provider vulnerability reporting owner",
			"ALL activity since the previous report, including persistent verification and validation, supplied to all necessary parties as Certification Data subject to CDS.",
			"Identify all detection/response and verification/validation activity sources, previous report cutoff, necessary-party recipients and Certification Data sharing paths.",
			"Persistently summarize all activity since the preceding report and share through the applicable Certification Data arrangements. Reconcile the reporting interval and current reporting status, including intentional interruptions.",
			"activity-source inventory, previous/current report cutoffs, report versions, detection/response and verification/validation reconciliations, recipient access/delivery records and reporting history.",
			"Trace every activity source across the complete inter-report period and confirm necessary-party availability under CDS; a vulnerability list alone may omit verification/validation activity.",
			"A current findings list without activity history, report-period reconciliation or necessary-party sharing evidence.",
		},
		"VER-RPT-VDT": {
			"Provide decision-useful lifecycle details for detected vulnerabilities other than accepted vulnerabilities.", "Provider vulnerability reporting owner",
			"Detected vulnerabilities being reported, UNLESS accepted; each listed field applies when applicable. Keep detection/evaluation times, reachability, exploitability, historical/current PAIN, completed and planned reductions, overdue status, supplementary information and final disposition distinct.",
			"Map vulnerability lifecycle fields to reporting fields and identify accepted-vulnerability exclusions and field-level applicability reasons.",
			"Populate every applicable detail field from the tracked vulnerability history. Explain overdue or likely-overdue status and supply responsibly determined supplementary information useful for federal risk assessment or mitigation.",
			"non-accepted vulnerability population, report versions, source lifecycle histories, per-field mappings/applicability explanations, reduction timestamps and target ratings, overdue explanations and disposition records.",
			"Reconcile all non-accepted findings and each source-listed field against the lifecycle record; distinguish historical/current ratings and completed/estimated reductions rather than overwriting history with today's score.",
			"A report containing only ID, severity and patch target, or blank required fields without applicability explanations.",
		},
		"VER-RPT-AVI": {
			"Make accepted vulnerabilities transparent with their current risk and acceptance rationale.", "Provider accepted-risk reporting owner",
			"Accepted vulnerabilities in vulnerability activity reports; required information includes tracking/detection/evaluation, reachability/exploitability, current PAIN, why accepted and responsibly useful supplementary information.",
			"Identify the accepted-vulnerability population and link acceptance reasons, current evaluations and detection records to the accepted-vulnerability reporting fields.",
			"Include every listed accepted-vulnerability field in reporting, including a substantive explanation of acceptance and supplementary information that responsibly helps agencies assess or mitigate risk.",
			"accepted-vulnerability register, acceptance explanations, current evaluation facts, source tracking/detection timestamps and report versions with field-level mappings.",
			"Reconcile accepted items to the report and verify current PAIN and acceptance reasons; do not silently drop accepted findings or reuse the non-accepted detail format with missing acceptance context.",
			"A risk-accepted label without a reason, current PAIN, reachability/exploitability or the required tracking history.",
		},
		"VER-RPT-NID": {
			"Balance responsible sensitive-detail handling with sufficient information for necessary-party risk decisions.", "Provider vulnerability disclosure owner",
			"Sensitive vulnerability information likely to lead to exploitation and all necessary parties' informed risk decisions; formal investigation/corrective-action action can supersede this requirement as the source note states.",
			"Identify sensitive exploit-enabling details, necessary-party decision needs and any actual formal investigation or corrective-action requirements affecting disclosure.",
			"Do not irresponsibly disclose exploit-enabling sensitive details, but disclose enough information for informed risk-based decisions to all necessary parties. Document the disclosure rationale and any formal superseding action.",
			"released report versions, necessary-party scope, sensitive-detail/disclosure decisions, risk-information sufficiency rationale and actual formal-action references where applicable.",
			"Assess both the prohibition and positive disclosure duty; ensure protective redaction does not remove needed risk facts and any claimed superseding action actually exists.",
			"Withholding all vulnerability information as sensitive, unrestricted exploit details, or a fabricated corrective-action/investigation exception.",
		},
		"VER-RPT-HLO": {
			"Show the breadth of vulnerability detection and response beyond scanner findings.", "Provider vulnerability program reporting owner",
			"ALL detection and response activities during the report period, including disclosure programs, bug bounties, penetration testing and assessments where conducted.",
			"Inventory the period's program activities and source records, including activities with no findings and externally performed testing.",
			"Include high-level overviews of all activities conducted during the period under the SHOULD recommendation, with scope and outcomes sufficient to understand the program's operation.",
			"period activity inventory, program/test/assessment records and report overviews mapped to each conducted activity.",
			"Reconcile overviews to the actual activity population and period; include no-finding work and avoid implying unperformed programs are mandatory.",
			"A scanner finding count used as the entire overview while disclosure, testing or assessment activity is omitted.",
		},
		"VER-RPT-RPD": {
			"Make responsible optional decisions about public or other-party vulnerability disclosure.", "Provider vulnerability disclosure owner",
			"Proposed vulnerability disclosures beyond necessary-party reporting, permitted if the provider determines disclosure will NOT likely lead to exploitation.",
			"Identify the proposed disclosure content/version, intended audience and facts relevant to likely exploitation from disclosure.",
			"If choosing to disclose, document the no-likely-exploitation determination and release the evaluated content responsibly. Preserve the option not to disclose publicly.",
			"provider disclosure determination, exploitation-likelihood rationale, evaluated content and actual release/recipient records if exercised.",
			"Compare released details and audience to the determination; do not confuse optional public disclosure with necessary-party reporting duties.",
			"Public posting without the provider's exploitation-likelihood determination or a fabricated obligation to publish vulnerability details.",
		},
		"VER-TFR-MHR": {
			"Deliver a consistent human-readable monthly account of detection and response activity.", "Provider vulnerability reporting owner",
			"Vulnerability detection and response activity reported to all necessary parties in a consistent human-readable format at least monthly.",
			"Define the report format, report-period boundaries, necessary-party recipient/access list and monthly publication process.",
			"Report activity at least monthly in the consistent human-readable format and verify availability to all necessary parties.",
			"consecutive monthly report versions and periods, format comparisons, publication timestamps and necessary-party delivery/access records.",
			"Compare report history to the monthly cadence and recipient population; verify human readability and consistent structure rather than accepting a JSON-only feed.",
			"A machine-readable feed alone or one undated report without monthly history and necessary-party access.",
		},
		"VER-TFR-MAV": {
			"Classify long-lived or expected long-lived unresolved vulnerabilities as accepted.", "Provider vulnerability risk owner",
			"Any vulnerability not or not expected to be fully mitigated or remediated within 192 days of evaluation; anticipated failure to meet the period also triggers categorization.",
			"Locate evaluation dates, actual full-mitigation/remediation evidence and credible completion forecasts; identify items already beyond or expected to exceed the period.",
			"Categorize qualifying vulnerabilities as accepted, including forecast exceedances rather than waiting for the period to expire; retain the evaluation-based clock and classification rationale.",
			"evaluation timestamps, remediation/full-mitigation status and forecasts, evaluation-plus-192-day calculations and accepted-category change history.",
			"Recalculate age from evaluation and assess forecast exceedances; verify partial mitigation is not treated as full mitigation and overdue status is not used to avoid accepted classification.",
			"A ticket creation-date clock, partial mitigation labeled complete, or waiting until day 192 despite already knowing full resolution will not occur in time.",
		},
		"VER-TFR-MRH": {
			"Make recent vulnerability history retrievable as JSON on the selected class's update cycle.", "Provider vulnerability data/API owner",
			"All recent historical detection/response activity, JSON automated retrieval by all necessary parties and persistent updates; MAY for A, SHOULD for B/C/D, with source class-specific monthly/14-day/7-day intervals.",
			"Map historical activity sources to JSON publication, authorized automated retrieval and access instructions; record the selected class, update process and any decision not to supply recommended machine-readable content.",
			"When adopted, provide recent historical activity as JSON for automated retrieval and update it persistently at the selected interval. Preserve optional/recommended force and the source alternative explanation for not providing machine-readable content where allowed.",
			"historical activity-to-JSON mapping, endpoint/access instructions, authorized retrieval results, consecutive update timestamps and completeness checks, or the permitted explanation for non-provision.",
			"Compare JSON history with source activity and the selected update interval; exercise automated retrieval as a necessary party and distinguish a download snapshot from a maintained historical feed.",
			"A JSON schema or endpoint URL with no usable history, update records or authorized automated retrieval; a monthly cycle substituted for Class C/D intervals.",
		},
		"VER-TFR-EVU": {
			"Complete vulnerability evaluation promptly within the class-specific detection-to-evaluation window.", "Provider vulnerability triage lead",
			"ALL detected vulnerabilities and the applicable VER-EVA evaluation, with the selected class's 14/7/5/2-day window from detection and SHOULD force.",
			"Reconcile detection sources to vulnerability records; preserve original detection timestamps and define completed evaluation records covering the applicable VER-EVA determinations.",
			"Evaluate every detected vulnerability within the selected class window from detection, retaining completed exploitability, reachability and impact decisions and applicable evaluation considerations.",
			"detection population/source timestamps, selected class, completed evaluation timestamps and substantive evaluation records with late/uncompleted items identified.",
			"Compute elapsed time from actual detection to completed evaluation across the full population; a triage acknowledgment or opened ticket is not completed evaluation.",
			"A ticket assignment within the window while contextual evaluation remains incomplete, or the wrong class's deadline.",
		},
		"VER-TFR-IRI": {
			"Escalate high-impact internet-reachable likely exploitable vulnerabilities under the class-specific incident rule.", "Provider vulnerability lead and incident commander",
			"Internet-reachable AND likely exploitable vulnerabilities with PAIN > 3, until partially mitigated to N3 or below; MAY for A/B and SHOULD for C/D.",
			"Link vulnerability evaluation records to incident handling, preserving reachability, exploitability, current PAIN and the selected class's escalation force.",
			"Where the conjunction is met, apply the selected class's permission/recommendation to treat the vulnerability as a FedRAMP Reportable Incident until evaluated partial mitigation reaches N3 or below. Track the actual threshold crossing.",
			"reachability/exploitability evaluations, PAIN history, class-specific escalation decision, incident linkage and executed mitigation/re-evaluation showing N3 or below when incident treatment ends.",
			"Check all entry predicates and the exit threshold; a scheduled fix or a lower scanner severity does not establish the required PAIN reduction.",
			"Incident closure without evaluated N3-or-below mitigation, or escalation rules that omit either reachability or likely exploitability.",
		},
		"VER-TFR-NRI": {
			"Handle the highest-impact non-internet-reachable likely exploitable vulnerabilities under their distinct incident rule.", "Provider vulnerability lead and incident commander",
			"NOT internet-reachable AND likely exploitable vulnerabilities with PAIN = 5, until partially mitigated to N4 or below; MAY for A/B/C and SHOULD for D.",
			"Link non-internet-reachable vulnerability evaluations to incident decisions, including exploitability, N5 impact and the class-specific permission/recommendation.",
			"Where the conjunction is met, apply the selected class force to incident treatment until evaluated partial mitigation reaches N4 or below; do not substitute the internet-reachable N3 threshold.",
			"non-reachability and likely-exploitability evidence, PAIN history, class-specific incident decision/linkage and mitigation/re-evaluation demonstrating N4 or below at exit.",
			"Verify N5 entry, non-reachability, likely exploitability and the N4-or-below exit; check that Class C's MAY was not promoted to SHOULD.",
			"An internet-reachable escalation template reused unchanged, or incident closure without the actual N4-or-below re-evaluation.",
		},
	})
}
